"""日志轮转。

按序号滚动日志文件：``app.log`` → ``app.log.1`` → ``app.log.2`` ……，
并按保留份数把最老的那些删掉。
"""

import os

from . import fsutil
from .errors import RotationError


class Rotator(object):
    """一个日志文件的轮转器。"""

    def __init__(self, path, keep=5):
        self.path = os.path.abspath(path)
        self.keep = int(keep)

    @property
    def directory(self):
        return os.path.dirname(self.path)

    @property
    def stem(self):
        return os.path.basename(self.path)

    def rotations(self):
        """返回当前存在的轮转文件名（按序号升序）。"""
        return fsutil.rotation_names(self.directory, self.stem)

    def rotate(self):
        """把当前日志滚成 ``.1``，并把已有轮转依次后移。

        返回本次被写入的新路径列表。
        """
        if not os.path.exists(self.path):
            return []

        moved = []
        for name in self.rotations():
            index = fsutil.rotation_index(name)
            src = os.path.join(self.directory, name)
            dst = "%s.%d" % (self.path, index + 1)
            fsutil.move(src, dst)
            moved.append(dst)

        dst = "%s.1" % self.path
        fsutil.move(self.path, dst)
        moved.append(dst)
        return moved

    def prune(self):
        """删除超出保留份数的轮转文件，返回被删除的名字列表。"""
        names = self.rotations()
        ordered = sorted(names, reverse=True)
        removed = []
        for name in ordered[self.keep:]:
            if fsutil.remove(os.path.join(self.directory, name)):
                removed.append(name)
        return removed

    def rotate_and_prune(self):
        """轮转并立刻整理保留份数。"""
        moved = self.rotate()
        if not moved:
            raise RotationError("nothing to rotate: %s" % self.path)
        self.prune()
        return moved

"""文件系统操作的薄封装。

这里的每个函数都要求「目标已经存在时也要成功」：日志轮转本质上是把一个
序号文件搬到下一个序号上，而下一个序号上往往已经有上一轮留下的残留。
"""

import os


def move(src, dst):
    """把 ``src`` 移动到 ``dst``。

    目标已存在时也应当成功（覆盖它），返回 ``dst``。
    """
    os.rename(src, dst)
    return dst


def remove(path):
    """删除一个文件；不存在时返回 ``False``。"""
    try:
        os.remove(path)
    except FileNotFoundError:
        return False
    return True


def rotation_names(directory, stem):
    """返回 ``directory`` 中形如 ``stem.<n>`` 的名字列表（升序）。"""
    names = []
    for name in os.listdir(directory):
        if not name.startswith(stem + "."):
            continue
        suffix = name[len(stem) + 1:]
        if suffix.isdigit():
            names.append(name)
    return sorted(names)


def rotation_index(name):
    """返回轮转文件名的序号。"""
    return int(name.rsplit(".", 1)[1])

"""wrotate 使用的异常类型。"""


class WRotateError(Exception):
    """本库所有异常的基类。"""


class RotationError(WRotateError):
    """轮转过程中出现不可恢复的错误。"""

"""wrotate 的基础行为测试（仓库自带，不得修改）。"""

import pytest

from wrotate import Rotator


@pytest.fixture()
def logdir(tmp_path):
    (tmp_path / "app.log").write_bytes(b"current")
    return tmp_path


def test_rotate_moves_current_to_one(logdir):
    Rotator(str(logdir / "app.log")).rotate()
    assert (logdir / "app.log.1").read_bytes() == b"current"
    assert not (logdir / "app.log").exists()


def test_rotate_with_no_current_file_is_noop(tmp_path):
    assert Rotator(str(tmp_path / "missing.log")).rotate() == []


def test_rotations_are_listed(logdir):
    (logdir / "app.log.1").write_bytes(b"one")
    assert Rotator(str(logdir / "app.log")).rotations() == ["app.log.1"]


def test_prune_keeps_requested_count(logdir):
    for i in range(1, 6):
        (logdir / ("app.log.%d" % i)).write_bytes(b"x")
    removed = Rotator(str(logdir / "app.log"), keep=3).prune()
    assert len(removed) == 2

