"""文件系统操作的薄封装。

这里的每个函数都要求「目标已经存在时也要成功」：日志轮转本质上是把一个
序号文件搬到下一个序号上，而下一个序号上往往已经有上一轮留下的残留。
"""

import os


def _replace(src, dst):
    """``os.replace`` 的最小封装：目标已存在时覆盖它。

    Windows 上 ``os.rename`` 在目标已存在时会抛 ``FileExistsError``，而上一轮
    异常退出留下的残留文件恰恰就占着目标序号，所以这里一律用 ``os.replace``：
    覆盖已存在的目标是它的正常语义，并且仍然是同一目录内的原子操作。
    """
    os.replace(src, dst)
    return dst


def move(src, dst):
    """把 ``src`` 移动到 ``dst``。

    目标已存在时也应当成功（覆盖它），返回 ``dst``。
    """
    return _replace(src, dst)


def restore(src, dst):
    """撤销一次 :func:`move`：把 ``src`` 搬回 ``dst``。

    回滚路径刻意不复用 :func:`move`：出错的往往就是搬运这一步（它可能被替换、
    被打桩，或者正被目标机器上的权限问题卡住），回滚必须自己还能走通，
    否则「失败即回到开始前的状态」就成了空话。
    """
    return _replace(src, dst)


def remove(path):
    """删除一个文件；不存在时返回 ``False``。"""
    try:
        os.remove(path)
    except FileNotFoundError:
        return False
    return True


def rotation_names(directory, stem):
    """返回 ``directory`` 中形如 ``stem.<n>`` 的名字列表（按序号升序）。

    排序必须按**序号**而不是按文件名的字典序，否则 ``stem.10`` 会排在
    ``stem.2`` 前面，轮转的先后次序与保留份数都会挑错文件。
    """
    names = []
    prefix = stem + "."
    for name in os.listdir(directory):
        if not name.startswith(prefix):
            continue
        suffix = name[len(prefix):]
        if not suffix.isdigit():
            continue
        # isdigit() 对 "²"、"٣" 这类字符同样成立，但它们不是我们认识的序号
        if not suffix.isascii():
            continue
        names.append(name)
    return sorted(names, key=rotation_index)


def rotation_index(name):
    """返回轮转文件名的序号。"""
    return int(name.rsplit(".", 1)[1])

